const project = $('Load Project Data').first().json;
const prompt = $('Load Accessibility Prompt').first().json;
const executionId = $input.first().json.id;

const briefing = typeof project.briefing === 'string' ? JSON.parse(project.briefing) : (project.briefing || {});
const design = typeof project.design_option === 'string' ? JSON.parse(project.design_option) : (project.design_option || {});

const rooms = Array.isArray(design.rooms_layout) ? design.rooms_layout : [];
const constraints = Array.isArray(briefing.constraints) ? briefing.constraints : [];
const objectives = Array.isArray(briefing.objectives) ? briefing.objectives : [];
const clientNeeds = Array.isArray(briefing.client_needs) ? briefing.client_needs : [];

const roomsText = rooms.map(r => typeof r === 'object' ? `- ${r.room || r.name || '?'}: ${r.scope || r.description || ''}` : `- ${r}`).join('\n');

const prompt_user = `Audita el cumplimiento de DB-SUA y accesibilidad para este proyecto.

PROYECTO: ${project.project_name}
Tipo: ${project.project_type} | Inmueble: ${project.property_type || 'no especificado'} | Área: ${project.property_area_m2} m²
Ubicación: ${project.location_city}, ${project.location_province}

DISEÑO ELEGIDO: ${design.title || 'no especificado'}
${design.description || ''}

ROOMS_LAYOUT (alcance por habitación):
${roomsText || 'No definido en el design'}

NOTAS TÉCNICAS DEL DISEÑO: ${(design.technical_notes || []).join('; ') || 'ninguna'}
LOGICA DE INTERVENCION: ${design.intervention_logic || 'no especificada'}

OBJETIVOS DEL BRIEFING: ${objectives.join('; ') || 'no especificados'}
NECESIDADES DEL CLIENTE: ${clientNeeds.join('; ') || 'no especificadas'}
RESTRICCIONES DETECTADAS: ${constraints.join('; ') || 'ninguna'}

Genera la auditoría completa según el esquema JSON.`;

// === STUDIO PROFILE INJECTION (B24) ===
const _studio = $('Load Studio Profile').first().json || {};
function _safeStudio(v){ if(v==null)return null; if(typeof v==='string'){try{return JSON.parse(v);}catch(e){return v;}} return v; }
const _id=_safeStudio(_studio.identity)||{};
const _priorities=_safeStudio(_studio.priorities)||[];
const _redLines=_safeStudio(_studio.red_lines)||[];
const _jur=_safeStudio(_studio.jurisdiction)||{};
const _SP_ACC_LINES=[];
_SP_ACC_LINES.push('Estudio: '+(_id.nombre_estudio||'estudio')+' ('+(_id.ciudad||'España')+'). Auditor de accesibilidad asistente del/la profesional.');
if(_jur.ccaa) _SP_ACC_LINES.push('JURISDICCIÓN: '+_jur.ccaa+'. Aplica DB-SUA del CTE + normativa autonómica de accesibilidad de '+_jur.ccaa+' si existe.');
if(_priorities.length){ _SP_ACC_LINES.push('PRIORIDADES DEL ESTUDIO (al ponderar gravedad):'); _priorities.forEach(p=>_SP_ACC_LINES.push((p.orden||'?')+'. '+(p.prioridad||'')+(p.detalle?' — '+p.detalle:''))); }
if(_redLines.length){ _SP_ACC_LINES.push('LÍNEAS ROJAS (no recomendar nunca):'); _redLines.forEach(l=>_SP_ACC_LINES.push('- '+(l.texto||''))); }
const _SP_ACC=_SP_ACC_LINES.join('\n');
// === END STUDIO PROFILE INJECTION ===
const _baseSystemPrompt = (prompt && prompt.content) ? prompt.content : 'Eres auditor de accesibilidad. Devuelve solo JSON.';
const systemPromptToUse = _SP_ACC + '\n\n' + _baseSystemPrompt;

return [{ json: {
  execution_id: executionId,
  project_id: project.id,
  project_name: project.project_name,
  prompt_system: systemPromptToUse,
  prompt_user,
  model: 'gpt-4o',
  temperature: 0.2,
  agent_name: 'agent_accessibility'
}}];

const llm = $input.first().json;
const project = $('Load Project Data').first().json;
const built = $('Build Prompt').first().json;
const text = llm.text || '';

let parsed = {};
let parseError = null;

try {
  const m = text.match(/\{[\s\S]*\}/);
  if (m) parsed = JSON.parse(m[0]);
  else throw new Error('No JSON found in LLM response');
} catch (e) {
  parseError = e.message;
  parsed = {
    applies_to_project: false,
    applies_justification: 'Generación automática fallida — revisar manualmente',
    overall_compliance: 'pending',
    compliance_issues: [],
    recommendations: [{ category: 'obligatorio', recommendation: 'Generar auditoría manualmente', justification: 'Error LLM: ' + parseError }],
    commercial_argumentation: ''
  };
}

return [{ json: {
  execution_id: built.execution_id,
  project_id: project.id,
  applies_to_project: !!parsed.applies_to_project,
  applies_justification: parsed.applies_justification || '',
  overall_compliance: parsed.overall_compliance || 'pending',
  compliance_issues: JSON.stringify(parsed.compliance_issues || []),
  recommendations: JSON.stringify(parsed.recommendations || []),
  commercial_argumentation: parsed.commercial_argumentation || '',
  content_json: JSON.stringify(parsed),
  parse_error: parseError
}}];
